import 'package:flutter/material.dart'; import '../services/safety_service.dart';
class VerificationScreen extends StatefulWidget{const VerificationScreen({super.key});@override State<VerificationScreen> createState()=>_S();}class _S extends State<VerificationScreen>{final s=SafetyService();String type='national_id';final note=TextEditingController();List<Map<String,dynamic>> rows=[];Future<void>load()async{rows=await s.myVerification();if(mounted)setState((){});} @override void initState(){super.initState();load();}Future<void>send()async{try{await s.requestVerification(type,note.text);note.clear();await load();if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Verification request submitted')));}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('Unable to submit verification: $e')));}} @override void dispose(){note.dispose();super.dispose();}
 @override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Verification')),body:ListView(padding:const EdgeInsets.all(16),children:[DropdownButtonFormField<String>(value:type,items:const[DropdownMenuItem(value:'national_id',child:Text('National ID')),DropdownMenuItem(value:'passport',child:Text('Passport')),DropdownMenuItem(value:'other',child:Text('Other'))],onChanged:(v)=>setState(()=>type=v!),decoration:const InputDecoration(labelText:'Document type')),TextField(controller:note,decoration:const InputDecoration(labelText:'Note')),const SizedBox(height:12),FilledButton(onPressed:send,child:const Text('Request verification')),const Divider(),...rows.map((r)=>ListTile(leading:const Icon(Icons.verified_user),title:Text('${r['document_type']}'),subtitle:Text('${r['status']}')))]));}
